INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 48, 'theory', 'Quiz: bytecode, the GIL and free threading');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 0, 'What is stored in the __pycache__ directory?', '["Module source texts", "Backup copies of files", "A cache of compiled bytecode (.pyc) tagged with the interpreter version", "An error log"]', 2, 'A module is compiled once, and when the source changes, the cache is rebuilt.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 1, 'What does the specializing adaptive interpreter (3.11+) do?', '["It removes the GIL", "It compiles everything to machine code ahead of time", "It speeds up only input and output", "It replaces frequently executed instructions with fast versions for stable types"]', 3, 'When types change, the specialization is rolled back, so it is best to keep types stable in hot spots.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 2, 'Why don''t threads speed up processor-bound calculations in CPython with the GIL enabled?', '["Threads are forbidden", "At any moment only one thread executes bytecode", "Threads use only one memory core", "Because of asynchrony"]', 1, 'For CPU-bound tasks, use processes, C extensions, subinterpreters or the no-GIL build.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 3, 'Does the GIL make code thread-safe?', '["Yes, completely", "Only for strings", "No: x += 1 consists of several instructions, and threads can switch between them", "Only for numbers"]', 2, 'Compound operations need to be protected with a Lock, or data should be passed through a Queue.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 4, 'How can you tell whether the GIL is enabled in a running interpreter (3.13+)?', '["sys._is_gil_enabled()", "os.gil()", "threading.gil_state()", "gc.gil()"]', 0, 'And sysconfig.get_config_var(''Py_GIL_DISABLED'') shows the build type (1 means free threads).');
